<?php
/** Proof — create and move (spec "Proof", 1): Marco opens the Acme pilot (T&M, NTE, budgets, monthly) active with Start now, himself staffed as principal, next billing the first of next month; a fixed bid; a retainer refused; the moves. */
require __DIR__ . '/lib.php';
$marco = as_member(27); $bea = as_member(28); $priya = as_member(26);
[$acme, $card] = fixture_client();
[$beta, ] = fixture_client('SMOKE Beta', 'BETA');

echo "1. Create\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Acme pilot', 'kind' => 'time_and_materials', 'start_date' => '2026-03-02', 'nte_amount' => '50000', 'budget_hours' => '200', 'budget_amount' => '40000', 'ai_budget_amount' => '2000',
    'markup_pct' => '10', 'billing_cadence' => 'monthly', 'po_number' => 'PO-77', 'description' => 'SMOKE a pilot', 'start_now' => 'yes']);
$eng = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $eng > 0 && ($b['number'] ?? '') === 'ENG-0001' && ($b['location'] ?? '') === '/engagements/' . $eng . '?notice=saved' && str_contains((string) $b['did'], '(active)'), "engagement_save: 200, ENG-0001, record_id $eng, active");
$row = q('SELECT status, currency, manager_member_id, department_id, next_billing_date, activated_at, expense_policy FROM engagements WHERE id = :e', ['e' => $eng])[0];
ok($row['status'] === 'active' && $row['currency'] === 'USD' && (int) $row['manager_member_id'] === 27 && (int) $row['department_id'] === 7 && $row['next_billing_date'] === '2026-04-01' && $row['activated_at'] !== null && json_decode($row['expense_policy'], true) == ['markup_pct' => 10], 'active, USD (the client\'s), Marco its manager, AI Strategy its practice (his primary department), next billing Apr 1, the expense policy');
ok(q('SELECT member_id, consulting_role_id, valid_from FROM engagement_members WHERE engagement_id = :e', ['e' => $eng]) === [['member_id' => 27, 'consulting_role_id' => role('principal'), 'valid_from' => '2026-03-02']], 'Marco is staffed as principal from the start date');
$log = activity('engagement.create', $since);
ok(count($log) === 1 && (int) $log[0]['engagement_id'] === $eng && (int) $log[0]['client_id'] === $acme && (int) $log[0]['department_id'] === 7 && str_contains((string) $log[0]['after'], '"number": "ENG-0001"'), 'engagement.create logged with engagement_id, client_id, department_id and the record');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $beta, 'name' => 'SMOKE Beta build', 'kind' => 'fixed_bid', 'budget_amount' => '120000', 'budget_hours' => '600', 'billing_cadence' => 'on_milestone', 'start_now' => 'no']);
$fixed = (int) $b['record_id'];
ok($c === 200 && q('SELECT status, next_billing_date, number FROM engagements WHERE id = :e', ['e' => $fixed])[0] === ['status' => 'draft', 'next_billing_date' => null, 'number' => 'ENG-0002'], 'a fixed bid for Beta with the fee: a draft, ENG-0002, no billing date (on milestone)');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Retainer', 'kind' => 'retainer']);
ok($c === 422 && str_contains(msg($b), 'Retainers are not in this version'), 'a retainer: 422 in words');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Fixed with NTE', 'kind' => 'fixed_bid', 'nte_amount' => '100']);
ok($c === 422 && isset(fields($b)['nte_amount']), 'a fixed bid with an NTE: 422 (field nte_amount)');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => '', 'kind' => 'nonsense', 'start_date' => '2026-05-01', 'end_date' => '2026-04-01', 'budget_hours' => '-3']);
ok($c === 422 && count(fields($b)) === 4, 'four bad fields: 422 naming each');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => 999999, 'name' => 'x', 'kind' => 'time_and_materials']);
ok($c === 422 && isset(fields($b)['client']), 'an unknown client: 422 (field client)');
[$c, $b] = act($priya, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE by Priya', 'kind' => 'time_and_materials']);
ok($c === 403 && msg($b) === 'You may not manage engagements.', 'a Consultant: 403 "You may not manage engagements."');

echo "2. Update keeps what it is not sent\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/save.php', ['engagement' => $eng, 'budget_hours' => '240']);
$row = q('SELECT name, nte_amount, budget_hours, po_number, status FROM engagements WHERE id = :e', ['e' => $eng])[0];
ok($c === 200 && $row['budget_hours'] === '240.00' && $row['name'] === 'SMOKE Acme pilot' && $row['nte_amount'] === '50000.00' && $row['po_number'] === 'PO-77' && $row['status'] === 'active', 'one field changed; the rest kept; the status untouched');
$log = activity('engagement.update', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true) === ['budget_hours' => '240.00'], 'engagement.update logs the one changed field');
[$c, $b] = act($marco, '/engagements/save.php', ['engagement' => $eng, 'kind' => 'fixed_bid']);
ok($c === 422 && isset(fields($b)['nte_amount']), 'turning it fixed bid while it carries an NTE: 422');
[$c, $b] = act($bea, '/engagements/save.php', ['engagement' => $eng, 'description' => 'SMOKE by Billing']);
ok($c === 200, 'Billing manages every engagement (billing.write)');
[$c, $d] = screen($marco, '/engagements/' . $eng);
ok($c === 200 && $d['engagement']['i_manage'] === true && $d['engagement']['budget']['budget_hours'] === '240.00' && $d['engagement']['budget']['ai_budget_amount'] === '2000.00' && count($d['engagement']['staffing']) === 1, 'the page: i_manage, the budget with the AI amount (Marco holds cost.view), the staffing');

echo "3. The moves\n";
[$c, $b] = act($marco, '/engagements/close.php', ['engagement' => $fixed]);
ok($c === 422 && msg($b) === 'A draft engagement becomes active or is cancelled', 'draft → closed refused by the guard, in its words');
[$c, $b] = act($marco, '/engagements/activate.php', ['engagement' => $fixed]);
ok($c === 200 && q('SELECT status, activated_at IS NOT NULL AS a FROM engagements WHERE id = :e', ['e' => $fixed])[0] === ['status' => 'active', 'a' => true] && ($b['status'] ?? '') === 'active', 'draft → active (activated_at set)');
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/hold.php', ['engagement' => $eng, 'reason' => 'SMOKE client paused']);
ok($c === 200 && (string) one('SELECT status FROM engagements WHERE id = :e', ['e' => $eng]) === 'on_hold' && json_decode((string) activity('engagement.hold', $since)[0]['after'], true) == ['status' => 'on_hold', 'reason' => 'SMOKE client paused'], 'active → on hold with a reason, logged');
[$c, $b] = act($marco, '/engagements/activate.php', ['engagement' => $eng]);
ok($c === 200 && (string) one('SELECT status FROM engagements WHERE id = :e', ['e' => $eng]) === 'active', 'on hold → active');
[$c, $b] = act($marco, '/engagements/activate.php', ['engagement' => $eng]);
ok($c === 422 && msg($b) === 'ENG-0001 is already active.', 'activating an active one: 422 "ENG-0001 is already active."');
[$c, $b] = act($marco, '/engagements/cancel.php', ['engagement' => $eng]);
ok($c === 422 && isset(fields($b)['reason']), 'cancel without a reason: 422 (field reason)');
[$c, $b] = act($marco, '/engagements/close.php', ['engagement' => $eng, 'reason' => 'SMOKE done']);
ok($c === 200 && q('SELECT status, closed_by, closed_at IS NOT NULL AS c FROM engagements WHERE id = :e', ['e' => $eng])[0] === ['status' => 'closed', 'closed_by' => 27, 'c' => true], 'closed with a reason: closed_by Marco, closed_at set');
[$c, $b] = act($marco, '/engagements/save.php', ['engagement' => $eng, 'name' => 'x']);
ok($c === 422 && str_contains(msg($b), 'is closed; reopen it'), 'a closed engagement cannot be changed: 422 in words');
[$c, $b] = act($marco, '/engagements/reopen.php', ['engagement' => $eng, 'reason' => 'SMOKE more work']);
ok($c === 200 && q('SELECT status, closed_by, closed_at FROM engagements WHERE id = :e', ['e' => $eng])[0] === ['status' => 'active', 'closed_by' => null, 'closed_at' => null], 'reopened: active, the close cleared');
[$c, $b] = act($marco, '/engagements/delete.php', ['engagement' => $eng]);
ok($c === 422 && str_contains(msg($b), 'was active and is never deleted'), 'deleting an active one: refused by the trigger in its words');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Draft to delete', 'kind' => 'time_and_materials', 'start_now' => 'no']);
$draft = (int) $b['record_id'];
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/delete.php', ['engagement' => $draft]);
ok($c === 200 && (int) one('SELECT count(*) FROM engagements WHERE id = :e', ['e' => $draft]) === 0 && count(activity('engagement.delete', $since)) === 1 && ($b['location'] ?? '') === '/engagements/?notice=deleted', 'a draft deleted, logged, lands on the list');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE To cancel', 'kind' => 'time_and_materials']);
$tc = (int) $b['record_id'];
[$c, $b] = act($marco, '/engagements/cancel.php', ['engagement' => $tc, 'reason' => 'SMOKE lost the deal']);
ok($c === 200 && (string) one('SELECT status FROM engagements WHERE id = :e', ['e' => $tc]) === 'cancelled', 'cancelled with a reason');
[$c, $b] = act($marco, '/engagements/activate.php', ['engagement' => $tc]);
ok($c === 422 && msg($b) === 'Engagement ' . one('SELECT number FROM engagements WHERE id = :e', ['e' => $tc]) . ' is cancelled and stays so', 'a cancelled one stays so, in the guard\'s words');
[$c, $d] = screen($marco, '/engagements/');
ok($c === 200 && !in_array($tc, array_column($d['engagements'], 'engagement_id'), true) && in_array($eng, array_column($d['engagements'], 'engagement_id'), true), 'the list leaves cancelled ones out by default');
[$c, $d] = screen($marco, '/engagements/?status=cancelled');
ok(count($d['engagements']) === 1 && $d['engagements'][0]['engagement_id'] === $tc, '?status=cancelled lists it');
[$c, $d] = screen($marco, '/engagements/?q=PO-77');
ok(count($d['engagements']) === 1 && $d['engagements'][0]['engagement_id'] === $eng, 'search by the PO finds the pilot');
[$c, $d] = screen($marco, '/engagements/?kind=fixed_bid');
ok(count($d['engagements']) === 1 && $d['engagements'][0]['engagement_id'] === $fixed, 'the kind filter');
finish();
